import { siteInfo } from "@/lib/site";
import type { MetadataRoute } from "next";

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: siteInfo.name,
    short_name: siteInfo.name,
    description: siteInfo.description,
    lang: "en-US",
    start_url: "/dashboard",
    scope: "/",
    display: "standalone",
    theme_color: "#0b120f",
    background_color: "#0b120f",
    // Generated by pwa-icon/[size]/route.tsx. The artwork is full-bleed with the mark inside the
    // safe zone, so each size doubles as a maskable icon.
    icons: [192, 512].flatMap((size) =>
      (["any", "maskable"] as const).map((purpose) => ({
        src: `/pwa-icon/${size}`,
        sizes: `${size}x${size}`,
        type: "image/png",
        purpose,
      })),
    ),
  };
}
